import json
import unittest
from pathlib import Path

CONFIG_PATH = Path(__file__).resolve().parent.parent / "vercel.json"


class VercelHeadersTest(unittest.TestCase):
    def setUp(self):
        self.config = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))

    def test_nosniff_su_tutte_le_risposte(self):
        trovata = any(
            voce.get("source") == "/(.*)"
            and any(
                coppia.get("key", "").lower() == "x-content-type-options"
                and coppia.get("value") == "nosniff"
                for coppia in voce.get("headers", [])
            )
            for voce in self.config.get("headers", [])
        )
        self.assertTrue(trovata)

    def test_clean_urls_invariato(self):
        self.assertIs(self.config["cleanUrls"], True)


if __name__ == "__main__":
    unittest.main()

